/// <summary>
/// CB756_ValidationOfABNToATOSystem.
/// Controller class of ABN validation batch job.
/// </summary>
class METABNValidationJobController extends SysOperationServiceController
{
}

Method.Source:
protected void new()
{
    super(classStr(METABNValidationJobService), methodStr(METABNValidationJobService, process), SysOperationExecutionMode::Synchronous);
}

/// <summary>
/// Defines caption.
/// </summary>
/// <returns>Caption</returns>
public ClassDescription defaultCaption()
{
    return "@MET:ABNValidation";
}

/// <summary>
/// Executes the batch job.
/// </summary>
/// <param name = "_args">
/// <c>Args</c>.
/// </param>
public static void main(Args _args)
{
    METABNValidationJobController controller = new METABNValidationJobController();
    controller.parmArgs(_args);
    controller.initContract();
    controller.startOperation();
}

    /// <summary>
    /// Initializes data contract.
    /// </summary>
    private void initContract()
    {
        METABNValidationJobContract contract;

        contract = this.getDataContractObject() as METABNValidationJobContract;

        if (contract)
        {
            METCustParameters custParameters = METCustParameters::Find();

            contract.parmThreadCount(custParameters.ABNValidationThreadCount);
        }
    }
